<?php require_once __DIR__.'/../app/bootstrap.php';require_admin();$active='applications';$pageTitle='আবেদন ও অনুসন্ধান';$flash=$_SESSION['flash']??'';unset($_SESSION['flash']);if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();if(isset($_POST['delete_application'])){$delId=(int)($_POST['id']??0);if($delId>0){$del=$pdo->prepare('DELETE FROM applications WHERE id=?');$del->execute([$delId]);$_SESSION['flash']=$del->rowCount()?'আবেদনটি মুছে ফেলা হয়েছে।':'আবেদনটি পাওয়া যায়নি।';}header('Location: applications.php');exit;}$id=(int)($_POST['id']??0);$status=$_POST['status']??'new';$allowed=['new','contacted','enrolled','closed'];if(in_array($status,$allowed,true)){$pdo->prepare('UPDATE applications SET status=? WHERE id=?')->execute([$status,$id]);$_SESSION['flash']='আবেদনের অবস্থা আপডেট হয়েছে।';}header('Location: applications.php');exit;}$filter=$_GET['status']??'';$where='';$params=[];if(in_array($filter,['new','contacted','enrolled','closed'],true)){$where='WHERE a.status=?';$params[]=$filter;}$st=$pdo->prepare('SELECT a.*,c.title course_title FROM applications a LEFT JOIN courses c ON c.id=a.course_id '.$where.' ORDER BY a.created_at DESC LIMIT 500');$st->execute($params);$rows=$st->fetchAll();$statuses=['new'=>'নতুন','contacted'=>'যোগাযোগ করা হয়েছে','enrolled'=>'ভর্তি সম্পন্ন','closed'=>'বন্ধ'];require __DIR__.'/_head.php';?><?php if($flash):?><div class="alert alert-success"><?=e($flash)?></div><?php endif;?><div class="panel"><div class="d-flex justify-content-between align-items-center gap-2 flex-wrap mb-3"><div><div class="section-label">কোর্স আবেদন ও যোগাযোগ</div><div class="hint">সর্বশেষ ৫০০টি আবেদন; এখানে দেওয়া তথ্য ব্যক্তিগতভাবে পরিচালনা করুন।</div></div><form method="get" class="d-flex gap-2"><select class="form-select" name="status" aria-label="অবস্থা ফিল্টার"><option value="">সব অবস্থা</option><?php foreach($statuses as $k=>$v):?><option value="<?=e($k)?>" <?=$filter===$k?'selected':''?>><?=e($v)?></option><?php endforeach;?></select><button class="btn btn-primary">ফিল্টার</button></form></div><div class="table-wrap"><table class="table" style="min-width:920px"><thead><tr><th>আবেদনকারী</th><th>ফোন</th><th>কোর্স</th><th>শিক্ষাগত যোগ্যতা / বার্তা</th><th>তারিখ</th><th>অবস্থা / কাজ</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="notice-title"><?=e($r['applicant_name'])?></td><td><a href="tel:<?=e($r['phone'])?>"><?=e($r['phone'])?></a><br><a target="_blank" rel="noopener" href="https://wa.me/<?=e(preg_replace('/\D+/','',$r['phone']))?>" class="small">WhatsApp</a></td><td><?=e($r['course_title']??'কোর্স নিষ্ক্রিয়/মুছে ফেলা হয়েছে')?></td><td><div><?=e($r['education'])?></div><div class="hint"><?=e($r['message'])?></div></td><td><?=e(date('d-m-Y H:i',strtotime($r['created_at'])))?></td><td><form method="post" class="d-flex gap-1"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><select class="form-select form-select-sm" name="status" aria-label="অবস্থা"><?php foreach($statuses as $k=>$v):?><option value="<?=e($k)?>" <?=$r['status']===$k?'selected':''?>><?=e($v)?></option><?php endforeach;?></select><button class="btn btn-sm btn-primary">সেভ</button></form><form method="post" class="mt-2" onsubmit="return confirm('এই আবেদনটি স্থায়ীভাবে মুছে ফেলবেন?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-sm btn-outline-danger" name="delete_application" value="1"><i class="fa-solid fa-trash me-1"></i> মুছুন</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="text-center muted py-4">কোনো আবেদন পাওয়া যায়নি।</td></tr><?php endif;?></tbody></table></div></div><?php require __DIR__.'/_foot.php';?>
